'use server'

import { updateTag } from 'next/cache'
import { addPost } from '@/lib/posts'

export async function createPost(formData: FormData) {
  const title = formData.get('title')
  const content = formData.get('content')

  if (typeof title !== 'string' || !title.trim()) {
    throw new Error('A title is required.')
  }
  if (typeof content !== 'string' || !content.trim()) {
    throw new Error('Post content is required.')
  }

  await addPost(title.trim(), content.trim())

  // Expire the tag immediately. The next read blocks for fresh data.
  updateTag('posts')
}
import { cacheTag } from 'next/cache'
import { readPosts } from '@/lib/posts'

export async function getPosts() {
  'use cache'

  cacheTag('posts')
  return readPosts()
}
import { randomUUID } from 'node:crypto'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'

export type Post = {
  id: string
  title: string
  content: string
  createdAt: string
}

const postsFile = path.join(process.cwd(), 'data', 'posts.json')

export async function readPosts(): Promise<Post[]> {
  try {
    return JSON.parse(await readFile(postsFile, 'utf8')) as Post[]
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return []
    throw error
  }
}

// Serialize writes in this process so concurrent submissions do not overwrite each other.
let pendingWrite: Promise<void> = Promise.resolve()

export function addPost(title: string, content: string): Promise<void> {
  const write = pendingWrite.then(async () => {
    const posts = await readPosts()
    posts.unshift({ id: randomUUID(), title, content, createdAt: new Date().toISOString() })
    await mkdir(path.dirname(postsFile), { recursive: true })
    await writeFile(postsFile, JSON.stringify(posts, null, 2))
  })

  pendingWrite = write.catch(() => {})
  return write
}
import { createPost } from './actions'
import { getPosts } from './posts'

export default async function Home() {
  const posts = await getPosts()

  return (
    <main>
      <h1>Posts</h1>
      <form action={createPost}>
        <p>
          <label htmlFor="title">Title</label>{' '}
          <input id="title" name="title" required />
        </p>
        <p>
          <label htmlFor="content">Content</label>{' '}
          <textarea id="content" name="content" required />
        </p>
        <button type="submit">Create post</button>
      </form>
      {posts.length === 0 ? (
        <p>No posts yet.</p>
      ) : (
        <ul>
          {posts.map((post) => (
            <li key={post.id}>
              <h2>{post.title}</h2>
              <p>{post.content}</p>
            </li>
          ))}
        </ul>
      )}
    </main>
  )
}
import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  cacheComponents: true,
}

export default nextConfig

